#include "director_task_wake2.hpp"
#include "resident/domains/tasks/task_exact_execution.hpp"
#include "resident/domains/affairs/affairs_model.hpp"
namespace hanmo::resident {namespace {
bool same(const SubjectRef&a,const SubjectRef&b){return a.kind==b.kind&&a.id==b.id;}
bool same(const SourceRef&a,const SourceRef&b){return a.domain==b.domain&&a.kind==b.kind&&a.id==b.id;}
}
Status visit_task_commitment_wakes2(const CommonStore&common,const TaskState&tasks,const AffairsState&affairs,const WorldMoment&actual,const std::function<Status(const SubjectWake2&)>&emit){
 if(!emit)return common_failure("TaskCommitmentWakeConsumerRequired");
 auto source=[&](const char*kind,const StableId&id,const auto&parties)->Status{SourceRef ref{"tasks",kind,id};auto at=read_task_result_source_moment(common,tasks,affairs,{ref,1});if(!at.ok)return {false,{},at.error};auto time=compare_world_moments(at.value,actual);if(!time.ok)return {false,{},time.error};if(time.value>0)return common_failure("FutureTaskCommitmentWake",id);return parties([&](const SubjectRef&subject){if(subject.id.empty())return common_failure("TaskCommitmentWakePartyMissing",id);return emit({subject,SubjectWakeKind2::commitment,ref,1,0});});};
 auto actor_parties=[&](const auto&actors){return [&actors](const auto&write)->Status{for(const auto&id:actors){auto r=write(SubjectRef{SubjectKind::actor,id});if(!r.ok)return r;}return common_success();};};
 auto pair_parties=[&](const SubjectRef&assignee,const StableId&executor){return [&assignee,&executor](const auto&write)->Status{auto r=write(assignee);if(!r.ok)return r;const SubjectRef named{SubjectKind::actor,executor};return same(assignee,named)?common_success():write(named);};};
 if(tasks.exact_execution){for(const auto&row:tasks.exact_execution->starts.rows()){auto r=source("task_action_started",row.first,actor_parties(row.second.participants));if(!r.ok)return r;}for(const auto&row:tasks.exact_execution->terminals.rows()){const auto*start=tasks.exact_execution->starts.find(row.second.start_source_id);if(!start)return common_failure("TaskExactTerminalStartMissing",row.first);auto r=source("task_action_finished",row.first,actor_parties(start->participants));if(!r.ok)return r;}}
 if(tasks.claim_establishment)for(const auto&row:tasks.claim_establishment->claim_establishment_sources.rows()){auto read=read_task_claim_established_source(common,tasks,affairs,{{"tasks","task_claim_established",row.first},1});if(!read.ok)return {false,{},read.error};const auto*c=tasks.contracts.find(read.value->contract_id);if(!c||!c->executor_actor_id)return common_failure("TaskClaimWakeContractMissing",row.first);auto r=source("task_claim_established",row.first,pair_parties(c->assignee,*c->executor_actor_id));if(!r.ok)return r;}
 if(tasks.state_need_tasks){const auto&s=*tasks.state_need_tasks;for(const auto&row:s.contracts.rows()){auto r=source("state_task_accepted",row.second.acceptance_id,pair_parties(row.second.assignee,row.second.executor_actor_id));if(!r.ok)return r;}for(const auto&row:s.closures.rows()){const auto*c=s.contracts.find(row.second.contract_id);if(!c)return common_failure("StateTaskContractMissing",row.first);auto r=source("state_task_closing",row.first,pair_parties(c->assignee,c->executor_actor_id));if(!r.ok)return r;}for(const auto&row:s.settlements.rows()){const auto*c=s.contracts.find(row.second.contract_id);if(!c)return common_failure("StateTaskContractMissing",row.first);auto r=source("state_task_settled",row.first,pair_parties(c->assignee,c->executor_actor_id));if(!r.ok)return r;}}
 if(tasks.transport_agreements)for(const auto&row:tasks.transport_agreements->agreements.rows()){const auto&terms=row.second.terms;auto r=source("task_carrier_agreement_accepted",row.first,[&](const auto&write){auto x=write(terms.principal);if(!x.ok)return x;return same(terms.principal,terms.carrier_subject)?common_success():write(terms.carrier_subject);});if(!r.ok)return r;}
 if(tasks.objective_base){for(const auto&row:tasks.objective_base->acceptances.rows()){const auto*t=tasks.tasks.find(row.second.task_id);if(!t)return common_failure("TaskObjectiveOwnerMissing",row.first);auto r=source("task_objective_accepted",row.first,[&](const auto&write){return write(SubjectRef{SubjectKind::actor,t->assignee});});if(!r.ok)return r;}for(const auto&row:tasks.objective_base->reports.rows()){const auto*t=tasks.tasks.find(row.second.task_id);if(!t)return common_failure("TaskObjectiveOwnerMissing",row.first);auto r=source("task_objective_report_received",row.first,pair_parties(row.second.recipient,t->assignee));if(!r.ok)return r;}}
 return common_success();
}
Status validate_director_task_commitment_wake2(const CommonStore&common,const TaskState&tasks,const AffairsState&affairs,const SubjectWake2&wake,const WorldMoment&actual){if(wake.kind!=SubjectWakeKind2::commitment||wake.source_schema!=1||wake.source_revision!=0||wake.actual_source.domain!="tasks")return common_failure("TaskCommitmentWakeSourceMismatch",wake.actual_source.id);bool found=false;auto valid=visit_task_commitment_wakes2(common,tasks,affairs,actual,[&](const SubjectWake2&v){if(same(v.subject,wake.subject)&&same(v.actual_source,wake.actual_source))found=true;return common_success();});if(!valid.ok)return valid;return found?common_success():common_failure("TaskCommitmentWakePartyMismatch",wake.actual_source.id);}
}
